SELECT COUNT(DISTINCT product) AS unique_products FROM sales;
--
SELECT AVG(price) AS avg_price FROM sales;
--
SELECT category, SUM(quantity) AS total_qty FROM sales GROUP BY category ORDER BY total_qty DESC;
--
SELECT product, SUM(price * quantity) AS revenue FROM sales GROUP BY product ORDER BY revenue DESC;
